import { MARATHI_14_CATEGORIES } from './marathiCategoriesDatabase';

// Hydrate 14-category words directly into master vocabulary map and word array
Object.values(MARATHI_14_CATEGORIES).forEach(categoryEntries => {
  categoryEntries.forEach(item => {
    if (item && item.word) {
      const cleanW = item.word.trim();
      const cleanC = item.clue ? item.clue.trim() : '';
      if (cleanW.length >= 2) {
        if (!IMPORTED_VOCABULARY_MAP[cleanW] && cleanC) {
          IMPORTED_VOCABULARY_MAP[cleanW] = cleanC;
        }
        if (!IMPORTED_VOCABULARY_WORDS.includes(cleanW)) {
          IMPORTED_VOCABULARY_WORDS.push(cleanW);
        }
      }
    }
  });
});

